SELECT 
FROM reading_subscription_purchase
WHERE status=#{status}
ORDER BY update_time ASC, id ASC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE reading_subscription_purchase
SET status='ACTIVATED', subscription_id=#{subscriptionId}, settled_at=#{settledAt},
    version=version+1, update_time=#{settledAt}
WHERE id=#{purchaseId} AND status='PENDING' AND version=#{expectedVersion}

UPDATE reading_subscription_purchase
SET status='PAID_REVIEW', settled_at=#{settledAt}, version=version+1,
    update_time=#{settledAt}
WHERE id=#{purchaseId} AND status='PENDING' AND version=#{expectedVersion}

UPDATE reading_subscription_purchase
SET status='FAILED', settled_at=#{settledAt}, version=version+1,
    update_time=#{settledAt}
WHERE id=#{purchaseId} AND status='PENDING' AND version=#{expectedVersion}

UPDATE reading_subscription_purchase
SET status='ACTIVATED', subscription_id=#{subscriptionId}, version=version+1,
    update_time=#{updatedAt}
WHERE id=#{purchaseId} AND status='PAID_REVIEW' AND version=#{expectedVersion}

UPDATE reading_subscription_purchase
SET status='REFUND_PENDING', version=version+1, update_time=#{updatedAt}
WHERE id=#{purchaseId} AND status='PAID_REVIEW' AND version=#{expectedVersion}
